import{money,baht,esc,today,addDays,monthStart,dateLabel,normalize,uid,sum,total,paid,balance,validateSale,scopedSales,scopedPayments,metrics,csv,createDemo,upgradeData,salesComparison,customerInsight,productTotals}from'./core.js';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9"/><circle cx="9" cy="7" r="4"/><path d="M16 3a4 4 0 0 1 0 8"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h16v11H5a3 3 0 0 1-3-3V6"/><path d="M21 12h-5v5h5"/>',chart:'<path d="M3 3v18h18M7 16v-5m5 5V7m5 9v-8"/>',building:'<path d="M3 21h18M5 21V5l7-2 7 2v16M9 8h1m4 0h1M9 12h1m4 0h1m-5 9v-5h4v5"/>',phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1.9.4 1.9.7 2.8a2 2 0 0 1-.5 2.1L8 9.9a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.8.7a2 2 0 0 1 1.8 2.1z"/>',report:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8m-8 4h5"/>',settings:'<path d="m9 3 1-1h4l1 3 3 1 3 1v4l-2 2-1 3-1 3h-4l-2-2-3-1-3-1v-4l2-2z"/><circle cx="12" cy="11" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10z"/>',receipt:'<path d="M4 3v18l4-2 4 2 4-2 4 2V3l-4 2-4-2-4 2zM8 9h8m-8 4h8"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM14 5l5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const STORAGE='freshy-clinic-demo-v1';let db;try{const saved=JSON.parse(localStorage.getItem(STORAGE));if(saved&&!saved.seedVersion)localStorage.setItem(STORAGE+'-legacy-backup',JSON.stringify(saved));db=saved?.version===1&&['customers','sales','payments','followups','branches','staff','products','audit'].every(k=>Array.isArray(saved[k]))?upgradeData(saved):createDemo();}catch{db=createDemo();}
try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch{}
const main=$('#main'),modal=$('#modal'),modalBody=$('#modalBody');let page='dashboard',customerTab='history',reportTab='sales',settingsTab='staff';let filters={branch:'',staff:'',from:monthStart(today()),to:today(),q:'',status:''};let followType='all',toastTimer;let draftItems=[];let filtersExpanded=false;let modalReturn=null;let detailBack=null;
const menu=[['dashboard','grid','ภาพรวม'],['customers','users','ลูกค้า'],['sales','wallet','ขายและรับเงิน'],['team','chart','ประวัติการขายเซล'],['branches','building','สาขา'],['followups','phone','ติดตามลูกค้า'],['reports','report','รายงาน'],['settings','settings','ตั้งค่า']];
const find=(collection,id)=>db[collection].find(x=>x.id===id)||{};
const branchName=id=>id?find('branches',id).name||'—':'ทุกสาขา',staffName=id=>find('staff',id).name||'—',customerName=id=>find('customers',id).name||'—';
const pill=(s,c='')=>`<span class="pill ${c}">${esc(s)}</span>`;
const button=(label,action,cls='',ico='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function save(action,target){db.audit.unshift({id:uid('a'),date:new Date().toISOString(),action,target,user:'ผู้ดูแลระบบ'});db.audit=db.audit.slice(0,200);try{localStorage.setItem(STORAGE,JSON.stringify(db));return true;}catch{toast('บันทึกในเครื่องไม่ได้ ข้อมูลอยู่ชั่วคราวในหน้านี้');return false;}}
function exportRows(rows,name){const blob=new Blob([csv(rows)],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Freshy-'+name+'-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const opts=(rows,value='',blank='ทั้งหมด')=>`${blank!==null?`<option value="">${esc(blank)}</option>`:''}${rows.map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(r.name)}</option>`).join('')}`;
function selectField(label,id,rows,value,blank='ทั้งหมด'){return`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${opts(rows,value,blank)}</select></div>`;}
function head(title,actions=''){return`<div class="page-head"><div><h1>${title}</h1><div class="date">${dateLabel(today())}</div></div><div class="actions">${actions}</div></div>`;}
function selectedPeriod(){const t=today();if(filters.from===monthStart(t)&&filters.to===t)return 'month';if(filters.from===t&&filters.to===t)return 'today';if(filters.from===addDays(t,-6)&&filters.to===t)return 'week';if(filters.from===addDays(t,-29)&&filters.to===t)return 'thirty';return 'custom';}
function filterBar({date=true,search=false,status=false,staff=true}={}){const count=Number(!!filters.staff)+Number(!!filters.status),period=selectedPeriod();return `<section class="filter-toolbar" aria-label="ตัวกรองข้อมูล"><div class="filter-primary">${search?`<div class="search quick-search">${icon('search')}<input id="search" value="${esc(filters.q)}" aria-label="ค้นหาลูกค้า" placeholder="ชื่อ / OPD / เบอร์โทร" autocomplete="off"></div>`:''}<select id="filterBranch" aria-label="สาขา">${opts(db.branches,filters.branch,'ทุกสาขา')}</select>${date?`<select id="filterPeriod" aria-label="ช่วงเวลา">${[['month','เดือนนี้'],['today','วันนี้'],['week','7 วันล่าสุด'],['thirty','30 วันล่าสุด'],['custom','กำหนดวันที่']].map(([v,l])=>`<option value="${v}" ${period===v?'selected':''}>${l}</option>`).join('')}</select>`:''}<button type="button" class="btn filter-toggle ${filtersExpanded?'selected':''}" id="filterToggle" aria-label="ตัวกรอง" aria-expanded="${filtersExpanded}" aria-controls="filterDetails">${icon('settings')}<span>ตัวกรอง${count?' ('+count+')':''}</span>${count?'<i class="filter-dot"></i>':''}</button></div><div class="filter-details" id="filterDetails" ${filtersExpanded?'':'hidden'}>${staff?selectField('เซล','filterStaff',db.staff.filter(s=>!filters.branch||(s.branchId===filters.branch||s.role==='owner')),filters.staff,'ทุกคน'):''}${date?`<div class="field"><label for="filterFrom">ตั้งแต่</label><input type="date" id="filterFrom" value="${filters.from}"></div><div class="field"><label for="filterTo">ถึง</label><input type="date" id="filterTo" value="${filters.to}"></div>`:''}${status?`<div class="field"><label for="filterStatus">สถานะ</label><select id="filterStatus">${['ทั้งหมด','ลูกค้าใหม่','ติดตาม','ซื้อแล้ว'].map(v=>`<option value="${v==='ทั้งหมด'?'':v}" ${filters.status===v?'selected':''}>${v}</option>`).join('')}</select></div>`:''}${button('รีเซ็ต','clearFilters','small')}</div></section>`;}

function comparisonBox(){const c=salesComparison(db,filters),label=c.percent===null?(c.current?'เริ่มมียอดขาย':'ยังไม่มียอดขาย'):c.percent===0?'เท่าเดิม':`${c.percent>0?'↑':'↓'} ${money(Math.abs(c.percent).toFixed(1))}%`;return `<div class="sales-comparison"><span class="${c.change<0?'text-red':'text-primary'}">${label}</span><span>เดือนก่อน ${baht(c.previous)}</span><small>${dateLabel(c.from)} – ${dateLabel(c.to)}</small></div>`;}
function kpis(){const m=metrics(db,filters);return`<div class="kpis">${[['ยอดรับเงินจริง',baht(m.received),'wallet',`${money(scopedPayments(db,filters).filter(p=>p.type!=='refund').length)} รายการรับเงิน`],['ยอดขาย',baht(m.sales),'chart',`${money(m.bills)} บิล`],['ค้างชำระ',baht(m.balance),'clock','ทุกวัน · สาขา / เซลที่เลือก'],['ลูกค้าที่ซื้อ',money(m.customers)+' คน','users','ตามช่วงวันที่เลือก']].map(([l,v,i,b])=>`<article class="kpi"><div class="kpi-top">${l}${icon(i)}</div><div class="kpi-value">${v}</div><div class="kpi-bottom">${b}</div>${l==='ยอดขาย'?comparisonBox():''}</article>`).join('')}</div>`;}

function dashboardKpis(){
 const m=metrics(db,filters),rows=scopedSales(db,filters).filter(s=>s.status!=='cancelled'),average=m.bills?m.sales/m.bills:0,highest=rows.length?Math.max(...rows.map(total)):0;
 const receivedCount=`${money(scopedPayments(db,filters).filter(p=>p.type!=='refund').length)} รายการรับเงิน`;
 // Keep the previous content as an inert size reference so each responsive card
 // retains its exact width and height, independent of the replacement copy.
 const original=[['ยอดรับเงินจริง',baht(m.received),'wallet',receivedCount],['ยอดขาย',baht(m.sales),'chart',`${money(m.bills)} บิล`],['ค้างชำระ',baht(m.balance),'clock','ทุกวัน · สาขา / เซลที่เลือก'],['ลูกค้าที่ซื้อ',money(m.customers)+' คน','users','ตามช่วงวันที่เลือก']];
 const cards=[['ยอดรับเงินจริง',baht(m.received),'wallet',receivedCount,`<div class="kpi-detail balance-detail"><span>ค้างชำระ ${baht(m.balance)}</span><small>ทุกวัน · สาขา / เซลที่เลือก</small></div>`],['ยอดขาย',baht(m.sales),'chart',`${money(m.bills)} บิล`,comparisonBox()],['ยอดเฉลี่ยต่อบิล',baht(average),'receipt',`บิลที่มีการซื้อสูงสุด ${money(highest)} บาท`,''],['ลูกค้าที่ซื้อ',money(m.customers)+' คน','users','ตามช่วงวันที่เลือก','']];
 return `<div class="kpis dashboard-kpis">${cards.map(([label,value,i,bottom,detail],n)=>{const [oldLabel,oldValue,oldIcon,oldBottom]=original[n];return `<article class="kpi"><div class="kpi-size-reference" aria-hidden="true" inert><div class="kpi-top">${oldLabel}${icon(oldIcon)}</div><div class="kpi-value">${oldValue}</div><div class="kpi-bottom">${oldBottom}</div>${n===1?comparisonBox():''}</div><div class="kpi-display"><div class="kpi-top">${label}${icon(i)}</div><div class="kpi-value">${value}</div><div class="kpi-bottom ${n===2?'kpi-highest':''}">${bottom}</div>${detail}</div></article>`;}).join('')}</div>`;
}
function table(headers,rows,empty='ไม่พบรายการ'){return`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th class="${h[1]||''}">${h[0]||h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`;}
function saleRows(sales){return sales.map(s=>{const b=balance(s,db);return`<tr><td><button class="link" data-action="saleDetail" data-id="${s.id}">${esc(s.code)}</button><small style="display:block">${dateLabel(s.date)}</small></td><td><button class="link" data-action="customer" data-id="${s.customerId}">${esc(customerName(s.customerId))}</button></td><td>${esc(branchName(s.branchId))}</td><td>${staffLink(s.staffId)}</td><td class="number">${money(total(s))}</td><td class="number">${money(paid(s,db))}</td><td>${s.status==='cancelled'?pill('ยกเลิก','gray'):b>0?pill('ค้าง '+money(b),'amber'):pill('ชำระครบ')}</td><td>${button('ดู','saleDetail','small','receipt').replace('data-action="saleDetail"',`data-action="saleDetail" data-id="${s.id}"`)}</td></tr>`;});}
const saleHeaders=[['เลขรายการ'],['ลูกค้า'],['สาขา'],['เซล'],['ยอดสุทธิ','number'],['รับสะสม','number'],['สถานะ'],['']];
function rankData(){return db.staff.filter(s=>(!filters.branch||(s.branchId===filters.branch||s.role==='owner'))&&(!filters.staff||s.id===filters.staff)).map(s=>({...s,m:metrics(db,{...filters,staff:s.id})})).sort((a,b)=>b.m.received-a.m.received);}
function rankPanel(){const list=rankData(),max=Math.max(1,...list.map(s=>s.m.received));return`<section class="panel"><div class="panel-head"><h2>ยอดรับเงินรายเซล</h2><a class="link" href="#team">ดูทั้งหมด ${icon('arrow')}</a></div><div class="panel-body">${list.map((s,i)=>`<div class="rank-row"><span class="rank-index">${String(i+1).padStart(2,'0')}</span><div><button class="link rank-name" data-action="staffHistory" data-id="${s.id}">${esc(s.name)}</button><div class="mini-bar"><span style="width:${Math.max(0,s.m.received/max*100)}%"></span></div></div><div class="rank-amount">${baht(s.m.received)}<small>${esc(branchName(s.branchId))}</small></div></div>`).join('')||'<p class="empty">ไม่พบเซล</p>'}</div></section>`;}
function revenueChart(){const start=filters.from||monthStart(today()),end=filters.to||today();const days=Math.max(1,Math.round((new Date(end)-new Date(start))/86400000)+1),size=Math.max(1,Math.ceil(days/4));let groups=[];const pays=scopedPayments(db,filters);for(let i=0;i<Math.min(4,Math.ceil(days/size));i++){const a=addDays(start,i*size),b=addDays(a,size-1),n=sum(pays.filter(p=>p.date>=a&&p.date<=b),p=>p.type==='refund'?-p.amount:p.amount);groups.push({label:a.slice(8)+'/'+a.slice(5,7),n});}const max=Math.max(1,...groups.map(g=>Math.abs(g.n)));return`<section class="panel"><div class="panel-head"><h2>รายรับตามวันที่รับเงิน</h2><span class="meta">บาท</span></div><div class="panel-body"><div class="chart">${groups.map(g=>`<div class="chart-col"><span class="chart-val">${money(g.n)}</span><div class="chart-bar" style="height:${Math.max(2,Math.abs(g.n)/max*85)}%;${g.n<0?'background:var(--red)':''}" title="${g.label}: ${money(g.n)} บาท"></div></div>`).join('')}</div><div class="chart-labels">${groups.map(g=>`<span>${g.label}</span>`).join('')}</div></div></section>`;}
function dashboard(){const recent=scopedSales(db,filters).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6),tasks=filteredFollowups().filter(f=>!f.done&&f.date<=today()).slice(0,4);return head('ภาพรวม',button('บันทึกการขาย','newSale','primary','plus'))+filterBar()+dashboardKpis()+`<div class="grid-two dashboard-trends">${revenueChart()}${rankPanel()}</div>${productPanel()}<section class="panel"><div class="panel-head"><h2>รายการขายล่าสุด</h2><a class="link" href="#sales">ดูทั้งหมด</a></div>${table(saleHeaders,saleRows(recent))}</section><div class="grid-two" style="margin-top:14px"><section class="panel"><div class="panel-head"><h2>ติดตามลูกค้า</h2><a class="link" href="#followups">ดูทั้งหมด</a></div><div class="panel-body">${tasks.map(f=>`<div class="list-line"><div><button class="link" data-action="customer" data-id="${f.customerId}">${esc(customerName(f.customerId))}</button><small>${esc(f.topic)} · ${esc(staffName(f.staffId))}</small></div><div>${pill(f.date<today()?'เกินกำหนด':'วันนี้',f.date<today()?'red':'amber')}<small>${dateLabel(f.date)}</small></div></div>`).join('')||'<div class="empty">ไม่มีรายการรอติดตาม</div>'}</div></section><section class="panel"><div class="panel-head"><h2>ช่องทางรับเงิน</h2><span class="meta">ตามช่วงวันที่</span></div><div class="panel-body">${['โอนเงิน','เงินสด','บัตรเครดิต'].map(method=>`<div class="summary-row"><span>${method}</span><strong>${baht(sum(scopedPayments(db,filters).filter(p=>p.method===method),p=>p.type==='refund'?-p.amount:p.amount))}</strong></div>`).join('')}</div></section></div>`;}
function filteredCustomers(){return db.customers.filter(c=>(!filters.branch||c.branchId===filters.branch||db.sales.some(s=>s.customerId===c.id&&s.branchId===filters.branch))&&(!filters.staff||c.staffId===filters.staff)&&(!filters.status||c.status===filters.status)&&(!filters.q||normalize([c.name,c.nickname,c.code,c.phone].join(' ')).includes(normalize(filters.q))));}
function customerSpend(c){return sum(db.sales.filter(s=>s.customerId===c.id&&s.status!=='cancelled'),s=>paid(s,db));}
function customers(){const rows=filteredCustomers();return head('ลูกค้า',button('Export CSV','exportCustomers','','down')+button('เพิ่มลูกค้า','addCustomer','primary','plus'))+filterBar({date:false,search:true,status:true})+`<section class="panel"><div class="panel-head"><h2>รายชื่อลูกค้า <span class="muted">${money(rows.length)}</span></h2><span class="meta">OPD / ประวัติ / การติดตาม</span></div>${table([['ลูกค้า'],['เบอร์โทร'],['ผู้ดูแล'],['สาขา'],['ยอดใช้จ่ายสะสม','number'],['สถานะ'],['']],rows.map(c=>`<tr><td><div class="name-cell"><div><button class="link name" data-action="customer" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.code)} · ${esc(c.source)}</small></div></div></td><td>${esc(c.phone||'—')}</td><td>${esc(staffName(c.staffId))}</td><td>${esc(branchName(c.branchId))}</td><td class="number">${money(customerSpend(c))}</td><td>${pill(c.status,c.status==='ติดตาม'?'amber':c.status==='ลูกค้าใหม่'?'blue':'')}</td><td><button class="icon-button" data-action="editCustomer" data-id="${c.id}" aria-label="แก้ไข ${esc(c.name)}">${icon('edit')}</button></td></tr>`))}<div class="table-foot"><span>${rows.length} รายการ</span><span>บัตรลูกค้าร่วมทุกสาขา</span></div></section>`;}
function sales(){let rows=scopedSales(db,filters).sort((a,b)=>b.date.localeCompare(a.date));if(filters.q)rows=rows.filter(s=>normalize([s.code,customerName(s.customerId),find('customers',s.customerId).phone,find('customers',s.customerId).code].join(' ')).includes(normalize(filters.q)));return head('ขายและรับเงิน',button('บันทึกการขาย','newSale','primary','plus'))+filterBar({search:true})+kpis()+`<section class="panel"><div class="panel-head"><h2>รายการขาย <span class="muted">${rows.length}</span></h2><span class="meta">ยอดรับสะสมรวมทุกวันที่ชำระ</span></div>${table(saleHeaders,saleRows(rows))}</section>`;}
function staffLink(id){return `<button class="link" data-action="staffHistory" data-id="${id}">${esc(staffName(id))}</button>`;}
function historyTable(rows){return table([['วันที่ / รายการ'],['ลูกค้า'],['สินค้า / บริการ'],['สาขา'],['ยอดขาย','number'],['รับสะสม','number'],['สถานะ']],rows.map(s=>`<tr><td><button class="link" data-action="saleDetail" data-id="${s.id}">${esc(s.code)}</button><small class="block">${dateLabel(s.date)}</small></td><td><button class="link" data-action="customer" data-id="${s.customerId}">${esc(customerName(s.customerId))}</button></td><td class="service-cell">${s.items.map(i=>`${esc(i.name)} × ${i.qty}`).join('<br>')}</td><td>${esc(branchName(s.branchId))}</td><td class="number">${money(total(s))}</td><td class="number">${money(paid(s,db))}</td><td>${s.status==='cancelled'?pill('ยกเลิก','gray'):balance(s,db)>0?pill('ค้างชำระ','amber'):pill('ชำระครบ')}</td></tr>`));}
function staffHistory(id){detailBack=()=>staffHistory(id);const st=find('staff',id),rows=db.sales.filter(s=>s.staffId===id).sort((a,b)=>b.date.localeCompare(a.date)),m=metrics(db,{staff:id});modalReturn=null;openModal('ประวัติการขาย · '+esc(st.name),`<div class="modal-content"><div class="staff-profile"><div><strong>${esc(st.name)}</strong><small class="block">${esc(branchName(st.branchId))} · ประวัติทั้งหมด</small></div></div><div class="stat-list"><div class="stat-small"><small>ยอดขายสะสม</small><strong>${baht(m.sales)}</strong></div><div class="stat-small"><small>รับเงินจริง</small><strong>${baht(m.received)}</strong></div><div class="stat-small"><small>บิล / ลูกค้า</small><strong>${m.bills} / ${m.customers}</strong></div></div></div>${historyTable(rows)}`);$('#modal').classList.add('history-dialog');}
function team(){const rows=rankData();return head('ประวัติการขายเซล',button('Export CSV','exportTeam','','down'))+filterBar()+kpis()+`<section class="panel"><div class="panel-head"><h2>ยอดขายรายพนักงาน</h2><span class="meta">${dateLabel(filters.from)} – ${dateLabel(filters.to)}</span></div>${table([['พนักงาน'],['สาขา'],['ยอดขาย','number'],['รับเงินจริง','number'],['ค้างชำระทั้งหมด','number'],['บิล','number'],['ลูกค้าที่ซื้อ','number']],rows.map((st,i)=>`<tr><td><div class="name-cell">${staffLink(st.id)}</div></td><td>${esc(branchName(st.branchId))}</td><td class="number">${money(st.m.sales)}</td><td class="number text-primary"><strong>${money(st.m.received)}</strong></td><td class="number">${money(st.m.balance)}</td><td class="number">${st.m.bills}</td><td class="number">${st.m.customers}</td></tr>`))}</section><section class="panel" style="margin-top:14px"><div class="panel-head"><h2>ประวัติการขาย</h2><span class="meta">ตามตัวกรอง</span></div>${historyTable(scopedSales(db,filters).sort((a,b)=>b.date.localeCompare(a.date)))}</section>`;}
function productPanel(){const rows=productTotals(db,filters);return `<section class="panel product-dashboard"><div class="panel-head"><h2>สินค้าที่ขาย</h2><span class="meta">${money(sum(rows,r=>r.qty))} รายการ</span></div>${table([['สินค้า / บริการ'],['จำนวน','number'],['ยอดก่อนส่วนลด','number']],rows.map(r=>`<tr><td>${esc(r.name)}</td><td class="number"><strong>${money(r.qty)}</strong></td><td class="number">${money(r.gross)}</td></tr>`))}</section>`;}

function branches(){const rows=db.branches.filter(b=>!filters.branch||b.id===filters.branch);return head('สาขา',button('เพิ่มสาขา','addBranch','primary','plus'))+filterBar({staff:false})+`<div class="cards">${rows.map(b=>{const m=metrics(db,{...filters,branch:b.id});return`<section class="panel branch-card"><div class="branch-top"><span class="branch-icon">${icon('building')}</span>${pill(b.active?'เปิดใช้งาน':'ปิดใช้งาน',b.active?'':'gray')}</div><h2>${esc(b.name)}</h2><small>${esc(b.address||'—')}</small><div class="summary-row"><span class="muted">รับเงินจริง</span><strong class="text-primary">${baht(m.received)}</strong></div><div class="summary-row"><span class="muted">ยอดขาย</span><strong>${baht(m.sales)}</strong></div><div class="summary-row"><span class="muted">บิล / ลูกค้า</span><span>${m.bills} / ${m.customers}</span></div><div class="summary-row"><span class="muted">พนักงาน</span><span>${db.staff.filter(s=>s.branchId===b.id).map(s=>esc(s.name)).join(', ')||'—'}</span></div><div class="actions" style="margin-top:12px">${button('ดูรายการ','viewBranch','small subtle').replace('data-action="viewBranch"',`data-action="viewBranch" data-id="${b.id}"`)}${button('แก้ไข','editBranch','small').replace('data-action="editBranch"',`data-action="editBranch" data-id="${b.id}"`)}</div></section>`;}).join('')}</div>`;}
function filteredFollowups(){return db.followups.filter(f=>(!filters.branch||f.branchId===filters.branch)&&(!filters.staff||f.staffId===filters.staff)&&(!filters.q||normalize(customerName(f.customerId)).includes(normalize(filters.q)))&&(followType==='all'||f.type===followType)).sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));}
function followups(){const rows=filteredFollowups(),pending=rows.filter(f=>!f.done);return head('ติดตามลูกค้า',button('เพิ่มรายการ','addFollowup','primary','plus'))+filterBar({date:false,search:true})+`<div class="stat-list"><div class="stat-small"><small>รอติดต่อ</small><strong>${pending.length}</strong></div><div class="stat-small"><small>เกินกำหนด</small><strong class="text-red">${pending.filter(f=>f.date<today()).length}</strong></div><div class="stat-small"><small>เสร็จแล้ว</small><strong class="text-primary">${rows.filter(f=>f.done).length}</strong></div></div><section class="panel"><div class="tabs">${[['all','ทั้งหมด'],['Sale Pitch','Sale Pitch'],['Follow up','Follow up']].map(([v,l])=>`<button class="tab ${followType===v?'active':''}" data-action="followType" data-id="${v}">${l}</button>`).join('')}</div>${table([['กำหนดติดตาม'],['ลูกค้า'],['ประเภท / เรื่อง'],['เซล / สาขา'],['ผลล่าสุด'],['']],rows.map(f=>`<tr><td>${dateLabel(f.date)}${!f.done&&f.date<today()?'<small class="text-red" style="display:block">เกินกำหนด</small>':''}</td><td><button class="link" data-action="customer" data-id="${f.customerId}">${esc(customerName(f.customerId))}</button></td><td>${esc(f.type)}<small style="display:block">${esc(f.topic)}</small></td><td>${esc(staffName(f.staffId))}<small style="display:block">${esc(branchName(f.branchId))}</small></td><td>${pill(f.outcome,f.done?'':'amber')}</td><td>${button(f.done?'ดูผล':'บันทึกผล','followResult','small').replace('data-action="followResult"',`data-action="followResult" data-id="${f.id}"`)}</td></tr>`))}</section>`;}
function reports(){let content='';if(reportTab==='sales'){const rows=scopedSales(db,filters).sort((a,b)=>b.date.localeCompare(a.date));content=table(saleHeaders,saleRows(rows));}else if(reportTab==='payments'){const rows=scopedPayments(db,filters).sort((a,b)=>b.date.localeCompare(a.date));content=table([['วันที่รับ / คืนเงิน'],['รายการ'],['ลูกค้า'],['สาขาขาย / รับเงิน'],['เซล'],['วิธีชำระ'],['จำนวนเงิน','number']],rows.map(p=>{const s=find('sales',p.saleId);return`<tr><td>${dateLabel(p.date)}</td><td><button class="link" data-action="saleDetail" data-id="${s.id}">${esc(s.code)}</button></td><td>${esc(customerName(s.customerId))}</td><td>${esc(branchName(s.branchId))}<small style="display:block">รับ: ${esc(branchName(p.receivingBranchId))}</small></td><td>${staffLink(s.staffId)}</td><td>${esc(p.method)}</td><td class="number ${p.type==='refund'?'text-red':''}">${p.type==='refund'?'-':''}${money(p.amount)}</td></tr>`;}));}else if(reportTab==='products'){const map=new Map();for(const s of scopedSales(db,filters).filter(s=>s.status!=='cancelled'))for(const i of s.items){const r=map.get(i.productId)||{name:i.name,qty:0,gross:0};r.qty+=i.qty;r.gross+=i.qty*i.price;map.set(i.productId,r);}content=table([['สินค้า / บริการ'],['จำนวน','number'],['ยอดก่อนส่วนลด','number']],[...map.values()].sort((a,b)=>b.gross-a.gross).map(r=>`<tr><td>${esc(r.name)}</td><td class="number">${r.qty}</td><td class="number">${money(r.gross)}</td></tr>`));}else{content=table([['สาขา'],['ยอดขาย','number'],['รับเงินจริง','number'],['ค้างชำระทั้งหมด','number'],['บิล','number']],db.branches.filter(b=>!filters.branch||b.id===filters.branch).map(b=>{const m=metrics(db,{...filters,branch:b.id});return`<tr><td>${esc(b.name)}</td><td class="number">${money(m.sales)}</td><td class="number">${money(m.received)}</td><td class="number">${money(m.balance)}</td><td class="number">${m.bills}</td></tr>`;}));}return head('รายงาน',button('Export CSV','exportReport','','down'))+filterBar()+kpis()+`<section class="panel"><div class="tabs">${[['sales','รายการขาย'],['payments','รับเงิน / คืนเงิน'],['products','สินค้า / บริการ'],['branches','สาขา']].map(([v,l])=>`<button class="tab ${reportTab===v?'active':''}" data-action="reportTab" data-id="${v}">${l}</button>`).join('')}</div>${content}</section>`;}
function settings(){const roles={owner:'CEO',manager:'ผู้จัดการ',sales:'เซล',assistant:'ผู้ช่วย'};return head('ตั้งค่า')+`<section class="panel"><div class="tabs">${[['staff','พนักงาน'],['permissions','สิทธิ์ผู้ใช้'],['products','สินค้า / บริการ'],['audit','ประวัติการแก้ไข']].map(([v,l])=>`<button class="tab ${settingsTab===v?'active':''}" data-action="settingsTab" data-id="${v}">${l}</button>`).join('')}</div>${settingsTab==='staff'?`<div class="panel-head"><h2>พนักงาน</h2>${button('เพิ่มพนักงาน','addStaff','small primary','plus')}</div>${table([['ชื่อ'],['สาขา'],['สิทธิ์'],['สถานะ'],['']],db.staff.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(branchName(s.branchId))}</td><td>${roles[s.role]}</td><td>${pill(s.active?'เปิดใช้งาน':'ปิดใช้งาน',s.active?'':'gray')}</td><td><button class="icon-button" data-action="editStaff" data-id="${s.id}" aria-label="แก้ไข ${esc(s.name)}">${icon('edit')}</button></td></tr>`))}`:settingsTab==='permissions'?`<div class="panel-head"><h2>สิทธิ์ผู้ใช้</h2></div>${table([['ส่วนงาน'],['เจ้าของ'],['ผู้จัดการ'],['พนักงาน']],[['ข้อมูลลูกค้า','ทุกสาขา','สาขาที่รับผิดชอบ','ลูกค้าที่รับผิดชอบ'],['ขายและรับเงิน','ทุกสาขา','สาขาที่รับผิดชอบ','รายการของตนเอง'],['รายงาน','ทุกสาขา','สาขาที่รับผิดชอบ','ยอดของตนเอง'],['ยกเลิก / คืนเงิน','อนุญาต','สาขาที่รับผิดชอบ','ไม่อนุญาต'],['ตั้งค่าผู้ใช้ / สาขา','อนุญาต','ไม่อนุญาต','ไม่อนุญาต']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`))}`:settingsTab==='products'?`<div class="panel-head"><h2>สินค้า / บริการ</h2>${button('เพิ่มรายการ','addProduct','small primary','plus')}</div>${table([['ชื่อ'],['หมวด'],['ราคา','number'],['']],db.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.category)}</td><td class="number">${money(p.price)}</td><td><button class="icon-button" data-action="editProduct" data-id="${p.id}" aria-label="แก้ไข ${esc(p.name)}">${icon('edit')}</button></td></tr>`))}`:`<div class="panel-head"><h2>ประวัติการแก้ไข</h2><span class="meta">${db.audit.length} รายการ</span></div>${db.audit.length?table([['วันเวลา'],['ผู้บันทึก'],['การเปลี่ยนแปลง'],['รายการ']],db.audit.map(a=>`<tr><td>${esc(new Date(a.date).toLocaleString('th-TH'))}</td><td>${esc(a.user)}</td><td>${esc(a.action)}</td><td>${esc(a.target)}</td></tr>`)):'<div class="empty">ยังไม่มีการแก้ไขในเครื่องนี้</div>'}`}</section>`;}
function render(){const active=menu.find(m=>m[0]===page)||menu[0];$('#breadcrumb').innerHTML='<span class=breadcrumb-brand>The Freshy Clinic / </span>'+active[2];$('#nav').innerHTML=menu.map(([id,i,l],n)=>`${n===7?'<div class="nav-divider"></div>':''}<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${l}</span>${id==='followups'?`<span class="badge">${db.followups.filter(f=>!f.done).length}</span>`:''}</a>`).join('');main.innerHTML=({dashboard,customers,sales,team,branches,followups,reports,settings}[page]||dashboard)();bindFilters();}
function bindFilters(){const pairs=[['filterBranch','branch'],['filterStaff','staff'],['filterFrom','from'],['filterTo','to'],['filterStatus','status']];for(const[id,key]of pairs){const el=$('#'+id);if(el)el.addEventListener('change',()=>{const next={...filters,[key]:el.value};if(key==='branch')next.staff='';if(next.from&&next.to&&next.from>next.to){toast('วันที่เริ่มต้องไม่อยู่หลังวันที่สิ้นสุด');el.value=filters[key];return;}filters=next;render();});}const toggle=$('#filterToggle');if(toggle)toggle.addEventListener('click',()=>{filtersExpanded=!filtersExpanded;render();$('#filterToggle').focus();});const period=$('#filterPeriod');if(period)period.addEventListener('change',()=>{const v=period.value,t=today();if(v==='custom')filtersExpanded=true;else{filters.to=t;filters.from=v==='today'?t:v==='week'?addDays(t,-6):v==='thirty'?addDays(t,-29):monthStart(t);}render();if(v==='custom')$('#filterFrom').focus();});const q=$('#search');if(q)q.addEventListener('input',()=>{filters.q=q.value;const pos=q.selectionStart;render();const next=$('#search');next.focus();next.setSelectionRange(pos,pos);});}

function openModal(title,body,footer=''){closeNav();modal.classList.remove('history-dialog');modalBody.innerHTML=`<div class="modal-head"><div class="modal-heading">${modalReturn?`<button class="icon-button" data-action="backModal" aria-label="ย้อนกลับ">${icon('arrow')}</button>`:''}<h2 id="modalTitle">${title}</h2></div><button class="icon-button" data-action="closeModal" aria-label="ปิด">${icon('close')}</button></div><div class="modal-scroll">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;document.documentElement.classList.add('modal-open');if(!modal.open)modal.showModal();$('.modal-scroll',modal).scrollTop=0;modal.scrollTop=0;$('.modal-head [aria-label=ปิด]',modal).focus({preventScroll:true});}
function formModal(title,body,submitLabel,onSubmit){openModal(title,`<form id="modalForm"><div class="modal-content">${body}</div><div class="modal-error" id="modalError" role="alert"></div></form>`,button('ยกเลิก',modalReturn?'backModal':'closeModal')+`<button class="btn primary" type="submit" form="modalForm">${submitLabel}</button>`);$('#modalForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const err=onSubmit(Object.fromEntries(new FormData(form)),form);if(err){$('#modalError').textContent=err;$('#modalError').scrollIntoView({block:'nearest'});}});}
modal.addEventListener('close',()=>{if(!modal.open){document.documentElement.classList.remove('modal-open');modalReturn=null;}});

const inputField=(label,name,value='',type='text',required=false,extra='')=>`<div class="field"><label for="m_${name}">${label}${required?' *':''}</label><input id="m_${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;
function customerForm(id){const c=id?find('customers',id):{};let photoDraft=c.photo||'',photoLoading=false,photoSequence=0;formModal(id?'แก้ไขลูกค้า':'เพิ่มลูกค้า',`<div class="photo-editor"><img id="customerPhotoPreview" class="customer-photo preview-photo" ${c.photo?`src="${esc(c.photo)}"`:'hidden'} alt="รูปลูกค้า"><div class="photo-controls"><label class="btn small" for="customerPhotoInput">เลือกรูปลูกค้า</label><input id="customerPhotoInput" class="photo-file-input" type="file" accept="image/jpeg,image/png,image/webp"><button type="button" class="btn small" id="removeCustomerPhoto" ${c.photo?'':'hidden'}>ลบรูป</button><small id="photoStatus" role="status"></small></div></div><div class="form-grid">${inputField('ชื่อเล่น + ชื่อจริง','name',c.name,'text',true,'maxlength="100"')}${inputField('ชื่อเล่น','nickname',c.nickname)}${inputField('เบอร์โทร','phone',c.phone,'tel',false,'inputmode="tel" maxlength="20"')}${inputField('LINE','line',c.line)}${inputField('วันเกิด','birthday',c.birthday,'date')}${inputField('ที่อยู่','address',c.address)}${selectField('สาขา','branchId',db.branches,c.branchId||filters.branch||'b1',null)}${selectField('ผู้ดูแล','staffId',db.staff,c.staffId||filters.staff||'st1',null)}<div class="field"><label for="source">ช่องทางที่มา</label><select name="source" id="source">${['Facebook','LINE','Walk-in','แนะนำ','อื่น ๆ'].map(s=>`<option ${s===c.source?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="status">สถานะ</label><select name="status" id="status">${['ลูกค้าใหม่','ติดตาม','ซื้อแล้ว'].map(s=>`<option ${s===c.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field full"><label for="note">หมายเหตุ</label><textarea name="note" id="note" maxlength="1000">${esc(c.note)}</textarea></div></div>`,'บันทึก',v=>{if(photoLoading)return 'กำลังเตรียมรูป กรุณารอสักครู่';v.name=v.name.trim();if(!v.name)return 'กรอกชื่อลูกค้า';v.phone=normalize(v.phone);if(v.phone&&!/^\d{9,10}$/.test(v.phone))return 'เบอร์โทรต้องเป็นตัวเลข 9–10 หลัก';if(v.phone&&db.customers.some(x=>x.id!==id&&normalize(x.phone)===v.phone))return 'เบอร์โทรนี้มีอยู่แล้ว กรุณาตรวจบัตรลูกค้าเดิม';const before=JSON.stringify(db);v.photo=photoDraft;if(id)Object.assign(c,v);else{const n=Math.max(0,...db.customers.map(x=>Number(x.code.replace(/\D/g,''))||0))+1;db.customers.unshift({...v,id:uid('c'),code:'FC'+String(n).padStart(4,'0'),createdAt:today()});}if(!save(id?'แก้ไขลูกค้า':'เพิ่มลูกค้า',v.name)){db=JSON.parse(before);return 'พื้นที่บันทึกในเครื่องไม่พอ กรุณาลดขนาดรูปแล้วลองอีกครั้ง';}modal.close();render();if(id)showCustomer(id,customerTab);toast('บันทึกลูกค้าแล้ว');});
const photoInput=$('#customerPhotoInput'),preview=$('#customerPhotoPreview'),remove=$('#removeCustomerPhoto'),status=$('#photoStatus');photoInput.addEventListener('change',async()=>{const file=photoInput.files?.[0];if(!file)return;const seq=++photoSequence;photoLoading=true;status.textContent='กำลังเตรียมรูป…';try{const next=await prepareCustomerPhoto(file);if(seq!==photoSequence)return;photoDraft=next;preview.src=next;preview.hidden=false;remove.hidden=false;status.textContent='';}catch(e){if(seq===photoSequence)status.textContent=e.message;}finally{if(seq===photoSequence){photoLoading=false;photoInput.value='';}}});remove.addEventListener('click',()=>{photoSequence++;photoLoading=false;photoDraft='';preview.removeAttribute('src');preview.hidden=true;remove.hidden=true;photoInput.value='';status.textContent='';});}

function treatmentPanel(insight){return `<div class="treatment-list">${insight.treatments.map(r=>`<div class="treatment-row"><div><strong>${esc(r.name)}</strong><small class="block">ล่าสุด ${dateLabel(r.latest)} · รอบ ${r.months} เดือน</small></div><div class="treatment-due">${pill(r.days<0?'เลยรอบติดตาม '+Math.abs(r.days)+' วัน':r.days===0?'ถึงรอบติดตามวันนี้':r.days<=30?'ใกล้ถึงรอบ · อีก '+r.days+' วัน':'อีก '+r.days+' วัน',r.days<0?'red':r.days<=30?'amber':'gray')}<small class="block">${dateLabel(r.due)}</small></div></div>`).join('')}</div>`;}
function showCustomer(id,tab='history'){detailBack=()=>showCustomer(id,tab);const c=find('customers',id);if(!c.id)return;customerTab=tab;const insight=customerInsight(db,id);const cs=db.sales.filter(s=>s.customerId===id).sort((a,b)=>b.date.localeCompare(a.date)),fs=db.followups.filter(f=>f.customerId===id).sort((a,b)=>b.date.localeCompare(a.date));let content='';if(tab==='profile')content=`<div class="detail-grid">${[['เบอร์โทร',c.phone],['LINE',c.line],['ผู้ดูแล',staffName(c.staffId)],['สาขา',branchName(c.branchId)],['ช่องทางที่มา',c.source],['วันเกิด',dateLabel(c.birthday)],['ที่อยู่',c.address],['วันที่เพิ่ม',dateLabel(c.createdAt)],['สถานะ',c.status],['หมายเหตุ',c.note]].map(([l,v])=>`<div><small>${l}</small><p>${esc(v||'—')}</p></div>`).join('')}</div>`;else if(tab==='history')content=table([['วันที่ / เลขรายการ'],['บริการ'],['ยอดสุทธิ','number'],['ค้างชำระ','number']],cs.map(s=>`<tr><td><button class="link" data-action="saleDetail" data-id="${s.id}">${esc(s.code)}</button><small style="display:block">${dateLabel(s.date)} · ${esc(branchName(s.branchId))}</small></td><td>${s.items.map(i=>esc(i.name)).join(', ')}${s.status==='cancelled'?'<small class="text-red" style="display:block">ยกเลิก</small>':''}</td><td class="number">${money(total(s))}</td><td class="number">${money(balance(s,db))}</td></tr>`));else content=`<div class="timeline">${fs.filter(f=>tab==='all'||f.type===tab).map(f=>`<div class="timeline-item"><small>${dateLabel(f.date)} · ${esc(f.type)} · ${esc(staffName(f.staffId))}</small><strong>${esc(f.topic)}</strong><p>${esc(f.outcome)}${f.note?' · '+esc(f.note):''}</p></div>`).join('')||'<div class="empty">ไม่มีประวัติการติดตาม</div>'}</div>`;
openModal('บัตรลูกค้า',`<div class="customer-head">${c.photo?`<button type="button" class="customer-photo-button" data-action="editCustomer" data-id="${id}" aria-label="เปลี่ยนรูปลูกค้า"><img class="customer-photo" src="${esc(c.photo)}" alt="รูป ${esc(c.name)}"></button>`:''}<div><h2>${esc(c.name)}</h2><small>${esc(c.code)} · ${esc(c.nickname||'—')}</small>${!c.photo?`<button class="link photo-link" data-action="editCustomer" data-id="${id}">เพิ่มรูป</button>`:''}</div>${button('แก้ไข','editCustomer','small','edit').replace('data-action="editCustomer"',`data-action="editCustomer" data-id="${id}"`)}</div><div class="modal-content" style="padding-top:0;padding-bottom:0"><div class="stat-list"><div class="stat-small"><small>ยอดใช้จ่ายสะสม</small><strong>${baht(customerSpend(c))}</strong></div><div class="stat-small"><small>ค้างชำระ</small><strong>${baht(sum(cs,s=>balance(s,db)))}</strong></div><div class="stat-small"><small>จำนวนบิล</small><strong>${cs.filter(s=>s.status!=='cancelled').length}</strong></div><div class="stat-small"><small>ไม่ได้มาแล้ว</small><strong>${insight.absent===null?'—':insight.absent+' วัน'}</strong></div><div class="stat-small"><small>Rank ยอดใช้จ่าย</small><strong>${insight.rank?'#'+insight.rank:'—'}</strong></div><div class="stat-small"><small>รับบริการล่าสุด</small><strong class="last-visit">${dateLabel(insight.last)}</strong></div></div>${treatmentPanel(insight)}</div><div class="tabs">${[['history','ประวัติซื้อ'],['profile','ข้อมูลลูกค้า'],['Sale Pitch','Sale Pitch'],['Follow up','Follow up']].map(([v,l])=>`<button class="tab ${v===tab?'active':''}" data-action="customerTab" data-id="${id}" data-tab="${v}">${l}</button>`).join('')}</div><div class="modal-content">${content}</div>`,button('ติดตามลูกค้า','customerFollowup').replace('data-action="customerFollowup"',`data-action="customerFollowup" data-id="${id}"`)+button('บันทึกการขาย','customerSale','primary','plus').replace('data-action="customerSale"',`data-action="customerSale" data-id="${id}"`));}
function prepareCustomerPhoto(file){return new Promise((resolve,reject)=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type)){reject(new Error('เลือกรูป JPG, PNG หรือ WebP'));return;}if(file.size>10*1024*1024){reject(new Error('รูปต้องมีขนาดไม่เกิน 10 MB'));return;}const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const scale=Math.min(1,512/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/jpeg',0.78);if(result.length>240000)throw new Error('รูปมีรายละเอียดมากเกินไป กรุณาเลือกรูปที่เล็กลง');resolve(result);}catch{reject(new Error('ไม่สามารถเตรียมรูปนี้ได้ กรุณาเลือกรูปอื่น'));}finally{URL.revokeObjectURL(url);}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('เปิดรูปนี้ไม่ได้ กรุณาเลือกรูป JPG, PNG หรือ WebP'));};img.src=url;});}
function saleCustomerPicker(id){const c=find('customers',id);return `<div class="field customer-picker"><label for="saleCustomerSearch">ลูกค้า / OPD *</label><input id="saleCustomerSearch" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="saleCustomerResults" autocomplete="off" placeholder="ค้นหา OPD / ชื่อ / เบอร์โทร" value="${c.id?esc(c.code+' · '+c.name):''}" required><input type="hidden" name="customerId" id="customerId" value="${esc(c.id||'')}"><div class="customer-options" id="saleCustomerResults" role="listbox" aria-label="ผลค้นหาลูกค้า" hidden></div></div>`;}
function bindSaleCustomerPicker(){const input=$('#saleCustomerSearch'),hidden=$('#customerId'),list=$('#saleCustomerResults');let matches=[],active=-1;const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;};const mark=()=>{[...list.querySelectorAll('[role=option]')].forEach((el,i)=>{el.setAttribute('aria-selected',String(i===active));if(i===active){input.setAttribute('aria-activedescendant',el.id);el.scrollIntoView({block:'nearest'});}});};const select=c=>{hidden.value=c.id;input.value=c.code+' · '+c.name;input.setCustomValidity('');close();input.focus();};const search=()=>{const q=normalize(input.value);matches=db.customers.filter(c=>!q||[c.code,c.name,c.nickname,c.phone].some(v=>normalize(v).includes(q))).sort((a,b)=>Number(normalize(b.code)===q)-Number(normalize(a.code)===q));active=-1;list.innerHTML=matches.length?matches.map((c,i)=>`<button type="button" role="option" id="sale-customer-option-${i}" data-customer-id="${esc(c.id)}" aria-selected="false"><span><strong>${esc(c.code)}</strong> · ${esc(c.name)}</span><small>${esc(c.phone||'')}</small></button>`).join(''):'<div class="customer-no-results">ไม่พบลูกค้า</div>';list.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant');};input.addEventListener('input',()=>{hidden.value='';input.setCustomValidity('');search();});input.addEventListener('focus',()=>{if(!hidden.value)search();});input.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)search();if(matches.length){active=(active+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;mark();}}else if(e.key==='Enter'&&!list.hidden){e.preventDefault();if(matches.length){select(matches[active<0?0:active]);}}});list.addEventListener('click',e=>{const option=e.target.closest('[data-customer-id]');if(option)select(find('customers',option.dataset.customerId));});input.closest('.customer-picker').addEventListener('focusout',e=>{if(!input.closest('.customer-picker').contains(e.relatedTarget))close();});$('#saleForm').addEventListener('submit',e=>{if(!db.customers.some(c=>c.id===hidden.value)){e.preventDefault();e.stopImmediatePropagation();input.setCustomValidity('เลือกลูกค้าจากผลค้นหาก่อนบันทึก');input.reportValidity();input.focus();search();}},true);}

function newSale(customerId=''){modal.close();page='sales';history.replaceState(null,'','#sales');draftItems=[{productId:db.products[0]?.id||'',qty:1,price:db.products[0]?.price||0}];$('#breadcrumb').innerHTML='<span class=breadcrumb-brand>The Freshy Clinic / </span>บันทึกการขาย';window.scrollTo(0,0);main.innerHTML=head('บันทึกการขาย',button('กลับรายการขาย','backSales'))+`<form id="saleForm"><div class="sales-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>ข้อมูลการขาย</h2><span class="meta">${pill('รายการใหม่')}</span></div><div class="form-section"><div class="form-grid">${saleCustomerPicker(customerId)}${inputField('วันที่ขาย','date',today(),'date',true)}${inputField('วันที่รับบริการ','serviceDate',today(),'date',false,`max="${today()}"`)}${selectField('สาขาที่ขาย','branchId',db.branches,filters.branch||db.branches[0]?.id,null)}${selectField('เซลเจ้าของยอด','staffId',db.staff.filter(s=>s.active&&(s.role==='owner'||s.branchId===(filters.branch||db.branches[0]?.id))),filters.staff||db.staff.find(s=>s.active&&(!filters.branch||(s.branchId===filters.branch||s.role==='owner')))?.id,null)}</div></div></section><section class="panel"><div class="panel-head"><h2>สินค้า / บริการ</h2>${button('เพิ่มรายการ','addItem','small','plus')}</div><div class="form-section"><div id="saleItems"></div><div class="form-grid">${inputField('ส่วนลด (บาท)','discount',0,'number',true,'min="0" step="0.01"')}<div class="field"><label for="saleNote">หมายเหตุ</label><input name="note" id="saleNote" maxlength="500"></div></div></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>ชำระเงิน</h2>${icon('wallet')}</div><div class="form-section"><div id="saleSummary"></div><div class="form-grid" style="margin-top:12px">${inputField('รับชำระ (บาท)','payment',draftItems[0].price,'number',true,'min="0" step="0.01"')}<div class="field"><label for="method">วิธีชำระ</label><select name="method" id="method"><option>โอนเงิน</option><option>เงินสด</option><option>บัตรเครดิต</option></select></div><div class="full">${selectField('สาขาที่รับเงิน','receivingBranchId',db.branches,filters.branch||db.branches[0]?.id,null)}</div></div><div class="error-text" id="saleError" role="alert"></div><button type="submit" class="btn primary" style="width:100%">${icon('check')} บันทึกการขาย</button></div></section></div></div></form>`;bindSaleCustomerPicker();renderItems();$('#saleForm').addEventListener('input',e=>{if(!e.target.closest('#saleItems'))updateSaleSummary();});$('#saleForm').addEventListener('submit',submitSale);$('#branchId').addEventListener('change',()=>{const st=db.staff.filter(s=>s.active&&(s.role==='owner'||s.branchId===$('#branchId').value));$('#staffId').innerHTML=opts(st,st[0]?.id,null);$('#receivingBranchId').value=$('#branchId').value;});}
function renderItems(){const el=$('#saleItems');if(!el)return;el.innerHTML=draftItems.map((i,n)=>`<div class="item-row" data-index="${n}"><div class="field"><label for="product${n}">สินค้า / บริการ</label><select id="product${n}" data-item="productId">${opts(db.products,i.productId,null)}</select></div><div class="field"><label for="qty${n}">จำนวน</label><input id="qty${n}" data-item="qty" type="number" min="1" max="1000" step="1" required value="${i.qty}"></div><div class="field"><label for="price${n}">ราคา / หน่วย</label><input id="price${n}" data-item="price" type="number" min="0" step="0.01" required value="${i.price}"></div><button class="icon-button" type="button" data-action="removeItem" data-id="${n}" aria-label="ลบรายการ ${n+1}" ${draftItems.length===1?'disabled':''}>${icon('close')}</button></div>`).join('');el.oninput=itemInput;updateSaleSummary();}
function itemInput(e){const row=e.target.closest('.item-row'),key=e.target.dataset.item;if(row&&key){const i=draftItems[Number(row.dataset.index)];if(key==='productId'){i.productId=e.target.value;i.price=find('products',i.productId).price;row.querySelector('[data-item="price"]').value=i.price;}else i[key]=Number(e.target.value);updateSaleSummary();}}
function updateSaleSummary(){const el=$('#saleSummary');if(!el)return;const discount=Number($('#m_discount').value||0),gross=sum(draftItems,i=>i.price*i.qty),net=Math.max(0,gross-discount),pay=Number($('#m_payment').value||0);el.innerHTML=`<div class="summary-row"><span class="muted">รวมสินค้า</span><strong>${baht(gross)}</strong></div><div class="summary-row"><span class="muted">ส่วนลด</span><span>−${baht(discount)}</span></div><div class="summary-row total"><span>ยอดสุทธิ</span><span>${baht(net)}</span></div><div class="summary-row"><span class="muted">ค้างชำระ</span><strong class="${net-pay>0?'text-red':'text-primary'}">${baht(Math.max(0,net-pay))}</strong></div>`;}
function submitSale(e){e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget)),s={id:uid('s'),code:'FS'+String(Math.max(0,...db.sales.map(x=>Number(x.code.replace(/\D/g,''))||0))+1).padStart(5,'0'),customerId:v.customerId,branchId:v.branchId,staffId:v.staffId,date:v.date,serviceDate:v.serviceDate,discount:Number(v.discount),note:v.note,items:draftItems.map(i=>({...i,name:find('products',i.productId).name})),status:'active',createdAt:new Date().toISOString()},payment=Number(v.payment),err=validateSale(s,payment);if(err){$('#saleError').textContent=err;return;}if(!db.staff.some(x=>x.id===s.staffId&&(x.role==='owner'||x.branchId===s.branchId)&&x.active)){$('#saleError').textContent='เลือกเซลที่ประจำสาขาที่ขาย';return;}db.sales.unshift(s);if(payment>0)db.payments.unshift({id:uid('p'),saleId:s.id,date:s.date,amount:payment,type:'payment',method:v.method,receivingBranchId:v.receivingBranchId,note:''});find('customers',s.customerId).status='ซื้อแล้ว';save('บันทึกการขาย',s.code);render();showSale(s.id);toast('บันทึกการขายแล้ว');}
function showSale(id){const s=find('sales',id);if(!s.id)return;const b=balance(s,db),ps=db.payments.filter(p=>p.saleId===id).sort((a,b)=>a.date.localeCompare(b.date));openModal('รายละเอียดการขาย',`<div class="modal-content receipt"><div class="receipt-head"><h3>THE FRESHY CLINIC</h3><small>${esc(s.code)} · ${dateLabel(s.date)}</small></div><div class="receipt-meta"><span>ลูกค้า: ${esc(customerName(s.customerId))}</span><span>${esc(find('customers',s.customerId).code)}</span></div><div class="receipt-meta"><span>สาขา: ${esc(branchName(s.branchId))}</span><span>เซล: ${esc(staffName(s.staffId))}</span></div>${table([['รายการ'],['จำนวน','number'],['ยอดรวม','number']],s.items.map(i=>`<tr><td>${esc(i.name)}</td><td class="number">${i.qty}</td><td class="number">${money(i.qty*i.price)}</td></tr>`))}<div class="summary-row"><span>ส่วนลด</span><span>${baht(s.discount)}</span></div><div class="summary-row total"><span>ยอดสุทธิ</span><span>${baht(total(s))}</span></div><div class="summary-row"><span>รับเงินสะสมสุทธิ</span><strong>${baht(paid(s,db))}</strong></div><div class="summary-row"><span>ค้างชำระ</span><strong>${baht(b)}</strong></div>${s.status==='cancelled'?`<p class="text-red">ยกเลิก · ${esc(s.cancelReason)}</p>`:''}${s.note?`<p><small>หมายเหตุ: ${esc(s.note)}</small></p>`:''}<h3 style="margin:15px 0 6px">ประวัติรับเงิน / คืนเงิน</h3>${ps.length?table([['วันที่'],['สาขาที่รับ / คืน'],['วิธี'],['จำนวนเงิน','number']],ps.map(p=>`<tr><td>${dateLabel(p.date)}</td><td>${esc(branchName(p.receivingBranchId))}</td><td>${esc(p.method)}</td><td class="number ${p.type==='refund'?'text-red':''}">${p.type==='refund'?'-':''}${money(p.amount)}</td></tr>`)):'<p class="muted">ยังไม่มีรายการรับเงิน</p>'}</div>`,`${s.status!=='cancelled'?button('ยกเลิก / คืนเงิน','cancelSale','danger').replace('data-action="cancelSale"',`data-action="cancelSale" data-id="${id}"`):''}${b>0?button('รับชำระเพิ่ม','addPayment','primary').replace('data-action="addPayment"',`data-action="addPayment" data-id="${id}"`):''}${button('พิมพ์','printReceipt')}`);}
function paymentForm(id){const s=find('sales',id),b=balance(s,db);formModal('รับชำระเพิ่ม · '+esc(s.code),`<div class="stat-small" style="margin-bottom:12px"><small>ค้างชำระ</small><strong>${baht(b)}</strong></div><div class="form-grid">${inputField('วันที่รับเงิน','date',today(),'date',true,`min="${s.date}"`)}${inputField('จำนวนเงิน','amount',b,'number',true,`min="0.01" max="${b}" step="0.01"`)}${selectField('สาขาที่รับเงิน','receivingBranchId',db.branches,s.branchId,null)}<div class="field"><label for="paymentMethod">วิธีชำระ</label><select id="paymentMethod" name="method"><option>โอนเงิน</option><option>เงินสด</option><option>บัตรเครดิต</option></select></div></div>`,'บันทึกรับเงิน',v=>{const n=Number(v.amount);if(!Number.isFinite(n)||n<=0||n>balance(s,db))return 'จำนวนเงินเกินยอดค้างชำระ';db.payments.push({...v,id:uid('p'),saleId:id,amount:n,type:'payment',note:''});save('รับชำระเพิ่ม',s.code);modal.close();render();showSale(id);toast('บันทึกรับเงินแล้ว');});}
function cancelSale(id){const s=find('sales',id),n=paid(s,db);formModal('ยกเลิก · '+esc(s.code),`<div class="summary-row"><span>ยอดคืนเงินทั้งหมด</span><strong>${baht(n)}</strong></div><div class="form-grid">${inputField('วันที่ยกเลิก / คืนเงิน','date',today(),'date',true,`min="${s.date}"`)}<div class="field"><label for="refundMethod">วิธีคืนเงิน</label><select id="refundMethod" name="method"><option>โอนเงิน</option><option>เงินสด</option><option>บัตรเครดิต</option></select></div><div class="field full"><label for="cancelReason">เหตุผล *</label><textarea name="reason" id="cancelReason" required maxlength="500"></textarea></div></div>`,'ยืนยันยกเลิก',v=>{if(!v.reason.trim())return 'กรอกเหตุผล';s.status='cancelled';s.cancelReason=v.reason.trim();if(n>0)db.payments.push({id:uid('p'),saleId:id,date:v.date,amount:n,type:'refund',method:v.method,receivingBranchId:s.branchId,note:v.reason});save('ยกเลิก / คืนเงิน',s.code+' · '+v.reason);modal.close();render();showSale(id);toast('ยกเลิกรายการแล้ว');});}
function followupForm(customerId=''){formModal('เพิ่มการติดตาม',`<div class="form-grid">${selectField('ลูกค้า','customerId',db.customers,customerId||db.customers[0]?.id,null)}${inputField('กำหนดติดตาม','date',today(),'date',true)}<div class="field"><label for="followupType">ประเภท</label><select name="type" id="followupType"><option>Sale Pitch</option><option>Follow up</option></select></div>${selectField('ผู้รับผิดชอบ','staffId',db.staff,filters.staff||db.staff[0]?.id,null)}${selectField('สาขา','branchId',db.branches,filters.branch||db.branches[0]?.id,null)}${inputField('เรื่องที่ติดตาม','topic','','text',true,'maxlength="150"')}<div class="field full"><label for="followNote">หมายเหตุ</label><textarea name="note" id="followNote" maxlength="1000"></textarea></div></div>`,'บันทึก',v=>{if(!v.topic.trim())return 'กรอกเรื่องที่ติดตาม';db.followups.unshift({...v,id:uid('f'),outcome:'รอติดต่อ',done:false,createdAt:today()});save('เพิ่มการติดตาม',customerName(v.customerId));modal.close();render();toast('บันทึกการติดตามแล้ว');});}
function followResult(id){const f=find('followups',id);formModal('ผลการติดตาม · '+esc(customerName(f.customerId)),`<div class="form-grid"><div class="field"><label for="outcome">ผลการติดต่อ</label><select name="outcome" id="outcome">${['รอติดต่อ','ติดต่อแล้ว','สนใจ','นัดหมายแล้ว','ไม่รับสาย','ไม่สนใจ'].map(s=>`<option ${s===f.outcome?'selected':''}>${s}</option>`).join('')}</select></div>${inputField('กำหนดติดตาม','date',f.date,'date',true)}<div class="field full"><label for="resultNote">หมายเหตุ</label><textarea name="note" id="resultNote" maxlength="1000">${esc(f.note)}</textarea></div><label class="checkline full"><input type="checkbox" name="done" ${f.done?'checked':''}>เสร็จสิ้นการติดตาม</label></div>`,'บันทึกผล',v=>{Object.assign(f,{...v,done:v.done==='on'});save('บันทึกผลติดตาม',customerName(f.customerId));modal.close();render();toast('บันทึกผลแล้ว');});}
function branchForm(id){const b=id?find('branches',id):{};formModal(id?'แก้ไขสาขา':'เพิ่มสาขา',`<div class="form-grid">${inputField('ชื่อสาขา','name',b.name,'text',true,'maxlength="100"')}<div class="field"><label for="branchStatus">สถานะ</label><select name="active" id="branchStatus"><option value="true">เปิดใช้งาน</option><option value="false" ${b.active===false?'selected':''}>ปิดใช้งาน</option></select></div><div class="full">${inputField('ที่อยู่ / ข้อมูลติดต่อ','address',b.address,'text',false,'maxlength="300"')}</div></div>`,'บันทึก',v=>{if(!v.name.trim())return 'กรอกชื่อสาขา';if(db.branches.some(x=>x.id!==id&&normalize(x.name)===normalize(v.name)))return 'ชื่อสาขานี้มีอยู่แล้ว';v.active=v.active==='true';if(id)Object.assign(b,v);else db.branches.push({...v,id:uid('b')});save(id?'แก้ไขสาขา':'เพิ่มสาขา',v.name);modal.close();render();toast('บันทึกสาขาแล้ว');});}
function staffForm(id){const s=id?find('staff',id):{};formModal(id?'แก้ไขพนักงาน':'เพิ่มพนักงาน',`<div class="form-grid">${inputField('ชื่อพนักงาน','name',s.name,'text',true,'maxlength="100"')}${selectField('สาขา','branchId',db.branches,s.branchId??db.branches[0]?.id,'ทุกสาขา (CEO)')}<div class="field"><label for="staffRole">สิทธิ์</label><select name="role" id="staffRole">${[['owner','CEO'],['manager','ผู้จัดการ'],['sales','เซล'],['assistant','ผู้ช่วย']].map(([v,l])=>`<option value="${v}" ${v===(s.role||'sales')?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="staffStatus">สถานะ</label><select name="active" id="staffStatus"><option value="true">เปิดใช้งาน</option><option value="false" ${s.active===false?'selected':''}>ปิดใช้งาน</option></select></div></div>`,'บันทึก',v=>{if(!v.name.trim())return 'กรอกชื่อพนักงาน';v.active=v.active==='true';if(id)Object.assign(s,v);else db.staff.push({...v,id:uid('st')});save(id?'แก้ไขพนักงาน':'เพิ่มพนักงาน',v.name);modal.close();render();toast('บันทึกพนักงานแล้ว');});}
function productForm(id){const p=id?find('products',id):{};formModal(id?'แก้ไขสินค้า / บริการ':'เพิ่มสินค้า / บริการ',`<div class="form-grid">${inputField('ชื่อ','name',p.name,'text',true,'maxlength="100"')}${inputField('หมวด','category',p.category,'text',true,'maxlength="50"')}${inputField('ราคา (บาท)','price',p.price||0,'number',true,'min="0" max="10000000" step="0.01"')}</div>`,'บันทึก',v=>{if(!v.name.trim())return 'กรอกชื่อ';v.price=Number(v.price);if(!Number.isFinite(v.price)||v.price<0)return 'ตรวจสอบราคา';if(id)Object.assign(p,v);else db.products.push({...v,id:uid('pr')});save(id?'แก้ไขบริการ':'เพิ่มบริการ',v.name);modal.close();render();toast('บันทึกบริการแล้ว');});}
function exportTeam(){exportRows([['เซล','สาขา','ยอดขาย','รับเงินจริง','ค้างชำระทั้งหมด','บิล','ลูกค้า'],...rankData().map(s=>[s.name,branchName(s.branchId),s.m.sales,s.m.received,s.m.balance,s.m.bills,s.m.customers])],'team');}
function exportReport(){let rows;if(reportTab==='payments')rows=[['วันที่','เลขรายการ','ลูกค้า','สาขาขาย','สาขารับเงิน','เซล','ประเภท','วิธีชำระ','จำนวนเงิน'],...scopedPayments(db,filters).map(p=>{const s=find('sales',p.saleId);return[p.date,s.code,customerName(s.customerId),branchName(s.branchId),branchName(p.receivingBranchId),staffName(s.staffId),p.type==='refund'?'คืนเงิน':'รับเงิน',p.method,p.type==='refund'?-p.amount:p.amount];})];else if(reportTab==='branches')rows=[['สาขา','ยอดขาย','รับเงินจริง','ค้างชำระทั้งหมด','บิล'],...db.branches.filter(b=>!filters.branch||b.id===filters.branch).map(b=>{const m=metrics(db,{...filters,branch:b.id});return[b.name,m.sales,m.received,m.balance,m.bills];})];else if(reportTab==='products'){const map=new Map();for(const s of scopedSales(db,filters).filter(s=>s.status!=='cancelled'))for(const i of s.items){const r=map.get(i.productId)||[i.name,0,0];r[1]+=i.qty;r[2]+=i.qty*i.price;map.set(i.productId,r);}rows=[['บริการ','จำนวน','ยอดก่อนส่วนลด'],...[...map.values()]];}else rows=[['วันที่ขาย','เลขรายการ','ลูกค้า','สาขา','เซล','ยอดสุทธิ','รับสะสม','ค้างชำระ','สถานะ'],...scopedSales(db,filters).map(s=>[s.date,s.code,customerName(s.customerId),branchName(s.branchId),staffName(s.staffId),total(s),paid(s,db),balance(s,db),s.status==='cancelled'?'ยกเลิก':'ปกติ'])];exportRows(rows,reportTab);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){case'staffHistory':staffHistory(id);break;case'closeModal':modalReturn=null;modal.close();break;case'backModal':{const back=modalReturn;modalReturn=null;if(back)back();else modal.close();break;}case'clearFilters':filters={branch:'',staff:'',from:monthStart(today()),to:today(),q:'',status:''};render();break;case'newSale':newSale();break;case'backSales':render();break;case'addCustomer':customerForm();break;case'editCustomer':modalReturn=modal.open?()=>showCustomer(id,customerTab):null;customerForm(id);break;case'customer':modalReturn=null;showCustomer(id);break;case'customerTab':showCustomer(id,el.dataset.tab);break;case'customerSale':newSale(id);break;case'customerFollowup':modalReturn=()=>showCustomer(id,customerTab);followupForm(id);break;case'saleDetail':modalReturn=modal.open?detailBack:null;showSale(id);break;case'addPayment':modalReturn=()=>showSale(id);paymentForm(id);break;case'cancelSale':modalReturn=()=>showSale(id);cancelSale(id);break;case'printReceipt':window.print();break;case'addItem':draftItems.push({productId:db.products[0]?.id,price:db.products[0]?.price||0,qty:1});renderItems();break;case'removeItem':if(draftItems.length>1)draftItems.splice(Number(id),1);renderItems();break;case'addFollowup':followupForm();break;case'followResult':followResult(id);break;case'followType':followType=id;render();break;case'reportTab':reportTab=id;render();break;case'settingsTab':settingsTab=id;render();break;case'addBranch':branchForm();break;case'editBranch':branchForm(id);break;case'viewBranch':filters.branch=id;filters.staff='';location.hash='sales';break;case'addStaff':staffForm();break;case'editStaff':staffForm(id);break;case'addProduct':productForm();break;case'editProduct':productForm(id);break;case'exportCustomers':exportRows([['OPD','ชื่อ','ชื่อเล่น','เบอร์โทร','LINE','ผู้ดูแล','สาขา','ช่องทางที่มา','สถานะ','ยอดใช้จ่ายสะสม'],...filteredCustomers().map(c=>[c.code,c.name,c.nickname,c.phone,c.line,staffName(c.staffId),branchName(c.branchId),c.source,c.status,customerSpend(c)])],'customers');break;case'exportTeam':exportTeam();break;case'exportReport':exportReport();break;}});
function closeNav(){$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menuToggle').setAttribute('aria-expanded','false');}
$('#menuToggle').innerHTML=icon('menu');$('#menuToggle').setAttribute('aria-expanded','false');$('#menuToggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#scrim').hidden=!open;$('#menuToggle').setAttribute('aria-expanded',String(open));});$('#scrim').addEventListener('click',closeNav);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();});
$('#themeToggle').innerHTML=icon('moon');try{document.documentElement.dataset.theme=localStorage.getItem('freshy-theme')||'light';}catch{}$('#themeToggle').addEventListener('click',()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('freshy-theme',t);}catch{}});
function route(){page=menu.some(m=>m[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard';closeNav();if(modal.open)modal.close();filters.q='';filtersExpanded=false;modalReturn=null;render();window.scrollTo(0,0);}window.addEventListener('hashchange',route);route();
